import {el,icon} from './render.js';
const MAX_TEXT=1024*1024;
function pict(name,size=32){const span=el('span','');span.innerHTML=icon(name,size);return span;}
function makeButton(label,action,signal,iconName){const b=el('button','bevel-button',label);if(iconName){b.prepend(pict(iconName,20));b.classList.add('toolbar-button');}b.type='button';b.addEventListener('click',action,{signal});return b;}
const bytes=s=>new TextEncoder().encode(s).length;
function pcComputer(){let abort,alive=false,services,target,panel,foot,selected='apps',info=null,root=null,relative='',requestSerial=0;
 const guard=fn=>async()=>{try{await fn();}catch(e){if(alive&&e.status!==499)services.notify(e.message);}};
 const setStatus=text=>{if(alive)foot.textContent=text;};
 async function loadDirectory(){const serial=++requestSerial;setStatus('폴더를 읽는 중...');const result=await services.pc.request('/files/list',{rootId:root.id,path:relative});if(!alive||serial!==requestSerial)return;panel.replaceChildren();const nav=el('div','app-toolbar');nav.append(makeButton('상위',guard(async()=>{relative=relative.split('/').slice(0,-1).join('/');await loadDirectory();}),abort.signal,'up'),makeButton('새로고침',guard(loadDirectory),abort.signal,'refresh'),makeButton('Finder에서 보기',guard(()=>services.pc.request('/files/reveal',{rootId:root.id,path:relative})),abort.signal,'folder'),makeButton('연결 해제',guard(async()=>{await services.pc.request('/files/disconnect',{rootId:root.id});root=null;relative='';render();}),abort.signal,'disconnect'));nav.firstChild.disabled=!relative;panel.append(nav);const address=el('div','pc-address recessed');address.append(pict('drive',20),el('span','',root.name+(relative?'/'+relative:'')));panel.append(address);const grid=el('div','file-grid recessed pc-file-grid');grid.setAttribute('role','listbox');grid.setAttribute('aria-label','실제 PC 폴더');for(const entry of result.entries){const b=el('button','file-item');b.type='button';b.append(pict(entry.type==='folder'?'folder':entry.type==='link'?'shortcut':'text',32),el('span','',entry.name));const open=guard(async()=>{const next=[relative,entry.name].filter(Boolean).join('/');if(entry.type==='folder'){relative=next;await loadDirectory();}else if(entry.type==='link')services.notify('연결 파일은 Finder에서 확인해 주세요.');else{const document=await services.pc.request('/files/read',{rootId:root.id,path:next});if(alive)services.openApp('pc-editor',{document});}});b.addEventListener('click',()=>{for(const sibling of grid.children)sibling.classList.remove('selected');b.classList.add('selected');if(matchMedia('(pointer: coarse)').matches)open();},{signal:abort.signal});b.addEventListener('dblclick',open,{signal:abort.signal});b.addEventListener('keydown',e=>{if(e.key==='Enter')open();},{signal:abort.signal});grid.append(b);}if(!result.entries.length)grid.append(el('p','pc-empty','폴더가 비어 있습니다.'));panel.append(grid);setStatus(`${result.entries.length}개 항목${result.truncated?' · 처음 500개 표시':''} · 실제 PC`);}
 function render(){if(!alive)return;panel.replaceChildren();for(const b of target.querySelectorAll('[data-pc-tab]'))b.classList.toggle('active',b.dataset.pcTab===selected);if(!services.pc.available){const setup=el('div','pc-setup');setup.append(pict('computer',64),el('h2','','내 컴퓨터 연결'));const message=el('p','','Mac용 실행기로 열면 실제 앱 실행, 파일 편집, 시스템 설정을 사용할 수 있습니다.');setup.append(message);const steps=el('ol');for(const text of ['실행기를 내려받고 압축을 풉니다.','RETRO OS.command를 두 번 클릭합니다.','로컬 화면에서 내 컴퓨터를 엽니다.'])steps.append(el('li','',text));setup.append(steps);const link=el('a','bevel-button pc-download','Mac용 실행기 내려받기');link.href='./downloads/retro-os-mac.zip';link.download='retro-os-mac.zip';setup.append(link,el('p','pc-note','이 웹사이트에는 PC 파일이나 제어 권한이 전달되지 않습니다.'));panel.append(setup);setStatus('로컬 실행기 연결 안 됨');return;}
 if(selected==='apps'){const banner=el('div','pc-device');banner.append(pict('computer',48));const d=el('div');d.append(el('strong','',info?.device||'이 Mac'),el('p','',info?`${info.system} · ${info.architecture} · ${info.memoryGB}GB RAM`:'연결 중...'));banner.append(d);panel.append(banner);const group=el('fieldset','pc-group');group.append(el('legend','','프로그램'));const grid=el('div','pc-app-grid');for(const app of info?.apps||[]){const b=makeButton(app.name,guard(async()=>{await services.pc.request('/apps/launch',{id:app.id});setStatus(app.name+' 실행됨');}),abort.signal);b.replaceChildren(pict(app.icon,32),el('span','',app.name));grid.append(b);}group.append(grid);panel.append(group);const drives=el('fieldset','pc-group');drives.append(el('legend','','드라이브'));const row=el('div','pc-drive-row');row.append(makeButton('PC 폴더 연결...',guard(async()=>{root=await services.pc.request('/files/pick-folder',{});relative='';selected='files';await loadDirectory();}),abort.signal,'drive'),makeButton('가상 디스크 (R:)',()=>services.openApp('explorer',{folderId:'root'}),abort.signal,'floppy'));drives.append(row);panel.append(drives);setStatus('로컬 연결됨 · 이 Mac');}
 else if(selected==='files'){if(root){guard(loadDirectory)();return;}const intro=el('div','pc-setup');intro.append(pict('drive',56),el('h2','','로컬 파일'));intro.append(makeButton('폴더 연결...',guard(async()=>{root=await services.pc.request('/files/pick-folder',{});relative='';await loadDirectory();}),abort.signal,'folder'),makeButton('파일 열기...',guard(async()=>{const document=await services.pc.request('/files/pick-file',{});if(alive)services.openApp('pc-editor',{document});}),abort.signal,'text'));intro.append(el('p','pc-note','선택한 UTF-8 텍스트 파일만 편집합니다. 최대 1MB.'));panel.append(intro);setStatus('선택한 파일·폴더만 연결');}
 else {const controls=el('div','pc-system-controls');const audio=el('fieldset','pc-group');audio.append(el('legend','','Mac 출력 음량'));const volume=el('input');volume.type='range';volume.min='0';volume.max='100';volume.value='50';volume.setAttribute('aria-label','실제 Mac 음량');const level=el('output','','50%');volume.addEventListener('input',()=>level.textContent=volume.value+'%',{signal:abort.signal});const muteLabel=el('label','pc-check');const muted=el('input');muted.type='checkbox';muteLabel.append(muted,document.createTextNode('음소거'));const audioButtons=el('div','pc-drive-row');audioButtons.append(makeButton('현재 음량 읽기',guard(async()=>{const data=await services.pc.request('/system/audio');if(!alive)return;volume.value=String(data.volume);level.textContent=data.volume+'%';muted.checked=data.muted;}),abort.signal),makeButton('적용',guard(async()=>{await services.pc.request('/system/audio',{volume:Number(volume.value),muted:muted.checked});setStatus('Mac 음량 적용됨');}),abort.signal));audio.append(volume,level,muteLabel,audioButtons);const appearance=el('fieldset','pc-group');appearance.append(el('legend','','Mac 화면 모드'));const row=el('div','pc-drive-row');for(const [dark,label]of [[false,'라이트'],[true,'다크']])row.append(makeButton(label,guard(async()=>{await services.pc.request('/system/appearance',{dark});setStatus('Mac 화면 모드 적용됨');}),abort.signal));appearance.append(row);controls.append(audio,appearance,el('p','pc-note','이 설정은 실제 Mac에 적용됩니다.'));panel.append(controls);setStatus('시스템 제어 · 사용자 조작 시 적용');}}
 return {mount(container,s){target=container;services=s;alive=true;abort=new AbortController();target.classList.add('pc-app');s.setTitle('내 컴퓨터');const menubar=el('div','app-menu');menubar.append(makeButton('파일 열기...',guard(async()=>{const document=await s.pc.request('/files/pick-file',{});if(alive)s.openApp('pc-editor',{document});}),abort.signal),makeButton('새로고침',guard(async()=>{if(!s.pc.available)return;info=await s.pc.request('/status');render();}),abort.signal));const tabs=el('div','pc-tabs');for(const [id,label]of [['apps','내 컴퓨터'],['files','파일'],['system','제어판']]){const b=makeButton(label,()=>{selected=id;render();},abort.signal);b.dataset.pcTab=id;tabs.append(b);}panel=el('div','pc-panel');foot=el('div','statusbar');target.append(menubar,tabs,panel,foot);render();if(s.pc.available)guard(async()=>{info=await s.pc.request('/status');if(alive)render();})();},unmount(){alive=false;requestSerial++;abort?.abort();target?.replaceChildren();}};
}
function pcEditor(options){let services,target,abort,editor,status,alive=false,dirty=false,busy=false;let doc=options.document||null;let saved=doc?.text||'';
 const update=()=>{if(!alive)return;services.setTitle(`${dirty?'* ':''}${doc?.name||'제목 없음'} — PC 메모장`);services.setDirty(dirty);status.textContent=`실제 PC · ${bytes(editor.value).toLocaleString()} B · ${dirty?'수정됨':'저장됨'}`;};
 const guard=fn=>async()=>{if(busy)return;busy=true;try{await fn();}catch(e){if(alive&&e.status!==499)services.notify(e.message);}finally{busy=false;}};
 const save=async(asNew=false)=>{if(bytes(editor.value)>MAX_TEXT)throw new Error('1MB를 넘는 문서는 저장할 수 없습니다.');const text=editor.value;if(!asNew&&doc?.id){if(!await services.modal({title:'PC 파일 저장',message:`이 Mac의 “${doc.name}” 파일을 덮어쓸까요?`,confirmText:'파일에 저장',cancelText:'취소'}))return;const result=await services.pc.request('/files/save',{id:doc.id,text,revision:doc.revision});if(!alive)return;doc={...doc,...result};}else{const result=await services.pc.request('/files/save-as',{name:doc?.name||'새 문서.txt',text});if(!alive)return;if(doc?.id)services.pc.request('/files/release',{id:doc.id}).catch(()=>{});doc=result;}saved=text;dirty=editor.value!==saved;update();services.notify('PC 파일에 저장했습니다.');};
 const discard=async()=>!dirty||!!await services.modal({title:'PC 메모장',message:'저장하지 않은 변경사항을 버릴까요?',confirmText:'버리기',cancelText:'계속 편집'});
 return {mount(container,s){target=container;services=s;alive=true;abort=new AbortController();target.classList.add('pc-editor');const menu=el('div','app-menu');menu.append(makeButton('열기...',guard(async()=>{if(!await discard())return;const next=await s.pc.request('/files/pick-file',{});if(!alive)return;if(doc?.id)s.pc.request('/files/release',{id:doc.id}).catch(()=>{});doc=next;saved=doc.text;editor.value=saved;dirty=false;update();}),abort.signal),makeButton('저장',guard(()=>save(false)),abort.signal),makeButton('다른 이름으로 저장',guard(()=>save(true)),abort.signal),makeButton('사본 다운로드',()=>s.download(doc?.name||'새 문서.txt',editor.value,'text/plain;charset=utf-8'),abort.signal));const tools=el('div','app-toolbar');tools.append(makeButton('실행 취소',()=>{editor.focus();document.execCommand('undo');},abort.signal,'back'),makeButton('다시 실행',()=>{editor.focus();document.execCommand('redo');},abort.signal,'forward'));editor=el('textarea','notepad-editor recessed');editor.setAttribute('aria-label','실제 PC 텍스트 파일');editor.spellcheck=false;editor.value=saved;editor.addEventListener('input',()=>{dirty=editor.value!==saved;update();},{signal:abort.signal});editor.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();guard(()=>save(e.shiftKey))();}},{signal:abort.signal});status=el('div','statusbar');target.append(menu,tools,editor,status);update();},beforeClose:discard,unmount(){alive=false;abort?.abort();if(doc?.id)services.pc.request('/files/release',{id:doc.id}).catch(()=>{});saved='';doc=null;editor.value='';target?.replaceChildren();}};
}
export function createPCApp(type,options={}){return type==='pc-editor'?pcEditor(options):pcComputer();}
